//! LOSAT's `MEMB_BIT` and `MASKLIST` interaction parity against official NCBI BLAST+ 2.17.0
//! (`tests/seqdb/memb_bit`, generated by `tests/seqdb/make_memb_bit_fixtures.py`).
//!
//! Covers valid bits (0, 1..=32, `+1`), invalid values and `ComputeMasks` parse order (`SEQIDLIST`
//! before `MEMB_BIT` before `TAXIDLIST`), nested/sibling conflicts (`SetMemBit`), direct volume
//! shadowing, multi-volume per-volume bits, top iteration range suppression, combinations with
//! `FIRST_OID`/`LAST_OID`, `OIDLIST` + `OID_MASK_TYPE 1`, `GILIST`, `SEQIDLIST`, user `-seqidlist`,
//! empty `.phr` header records (`filters_header_sets`), `MASKLIST` + `MEMB_BIT` + `.nog`-less
//! fallback + conflict, `blastdbcheck -verbosity 3` (`seqdbvol.hpp:881`), and search programs
//! (`blastp`, `blastx`, `psiblast`, `blastn`, `tblastn`, `tblastx`) at both `-num_threads 1` and
//! `-num_threads 4`. Also checks LOSAT's explicit refusal of `MEMB_BIT > 32` on deflines with
//! memberships (C++ shift UB) and non-UTF-8 alias/DB directory paths.
//!
//! NCBI is never invoked here: all expected outputs are frozen from the official Linux x64 2.17.0
//! oracle and mapped to LOSAT's words through `losat::wording::losat_output_bytes`.

#![cfg(target_os = "linux")]

use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};
use std::process::Command;

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/seqdb/memb_bit")
}

struct Case {
    name: String,
    cwd: String,
    words: Vec<String>,
}

fn cases() -> Vec<Case> {
    let table = std::fs::read_to_string(fixtures().join("cases.tsv")).unwrap();
    table
        .lines()
        .filter(|line| !line.is_empty())
        .map(|line| {
            let mut fields = line.split('\t').map(str::to_string);
            let name = fields.next().unwrap();
            let cwd = fields.next().unwrap();
            Case {
                name,
                cwd,
                words: fields.collect(),
            }
        })
        .collect()
}

struct TempDir(PathBuf);

impl TempDir {
    fn new(label: &str) -> Self {
        let base = std::fs::canonicalize(std::env::temp_dir()).unwrap();
        let dir = base.join(format!("losat-memb-bit-{label}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        TempDir(dir)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn copy_tree(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for entry in std::fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let dst = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_tree(&entry.path(), &dst);
        } else {
            std::fs::copy(entry.path(), dst).unwrap();
        }
    }
}

fn run_losat(root: &Path, cwd: &Path, words: &[String], extra: &[&str]) -> (i32, Vec<u8>, Vec<u8>) {
    let mut command = Command::new(env!("CARGO_BIN_EXE_losat"));
    command
        .current_dir(cwd)
        .env("HOME", root)
        .args(words)
        .args(extra);
    for (name, _) in std::env::vars_os() {
        let name_str = name.to_string_lossy();
        let losat = name_str.starts_with("LOSAT_") && name_str != "LOSAT_BLASTX_WORKER_LOG";
        if losat || name_str.starts_with("NCBI_CONFIG") || name_str == "BLASTDB" {
            command.env_remove(name);
        }
    }
    let output = command.output().expect("run losat");
    let root_str = root.to_str().unwrap();
    let unroot = |bytes: Vec<u8>| {
        String::from_utf8_lossy(&bytes)
            .replace(root_str, "<R>")
            .into_bytes()
    };
    (
        output.status.code().unwrap_or(-1),
        unroot(output.stdout),
        unroot(output.stderr),
    )
}

fn expected(name: &str) -> (i32, Vec<u8>, Vec<u8>) {
    let dir = fixtures().join("expected");
    let read = |ext: &str| std::fs::read(dir.join(format!("{name}.{ext}"))).unwrap();
    let rc = String::from_utf8(read("rc"))
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    let mapped = |bytes: Vec<u8>| losat::wording::losat_output_bytes(&bytes).into_owned();
    (rc, mapped(read("stdout")), mapped(read("stderr")))
}

fn is_search(case: &Case) -> bool {
    matches!(
        case.words[0].as_str(),
        "blastp" | "blastn" | "blastx" | "tblastn" | "tblastx" | "psiblast"
    )
}

fn first_diff(got: &[u8], want: &[u8]) -> String {
    if got == want {
        return "equal".to_string();
    }
    let g = String::from_utf8_lossy(got);
    let w = String::from_utf8_lossy(want);
    let mut gl = g.split_inclusive('\n');
    let mut wl = w.split_inclusive('\n');
    for n in 1.. {
        match (gl.next(), wl.next()) {
            (None, None) => break,
            (a, b) if a != b => return format!("line {n}: got {a:?} != want {b:?}"),
            _ => {}
        }
    }
    "diff".to_string()
}

#[test]
fn memb_bit_and_masklist_match_frozen_ncbi_oracle() {
    let root = TempDir::new("oracle");
    copy_tree(&fixtures().join("db"), &root.0.join("db"));
    copy_tree(&fixtures().join("in"), &root.0.join("in"));

    let mut problems = Vec::new();
    for case in cases() {
        let want = expected(&case.name);
        let cwd = root.0.join(&case.cwd);
        let got = run_losat(&root.0, &cwd, &case.words, &[]);
        if got != want {
            problems.push(format!(
                "{}: rc {} (want {}), stdout {}, stderr {}",
                case.name,
                got.0,
                want.0,
                first_diff(&got.1, &want.1),
                first_diff(&got.2, &want.2),
            ));
        }
        if is_search(&case) {
            let got4 = run_losat(&root.0, &cwd, &case.words, &["-num_threads", "4"]);
            if got4 != want {
                problems.push(format!(
                    "{} -num_threads 4: rc {} (want {}), stdout {}, stderr {}",
                    case.name,
                    got4.0,
                    want.0,
                    first_diff(&got4.1, &want.1),
                    first_diff(&got4.2, &want.2),
                ));
            }
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

#[test]
fn memb_bit_past_32_refuses_memberships() {
    let root = TempDir::new("gt32");
    let db_dir = root.0.join("db");
    copy_tree(&fixtures().join("db"), &db_dir);

    // Entry with memberships (P00001.1): refused explicitly (C++ shift UB).
    // Deterministic paths (`-info` and entries without memberships) are frozen in `cases.tsv`.
    let args: Vec<String> = [
        "blastdbcmd",
        "-db",
        "mb_33",
        "-dbtype",
        "prot",
        "-entry",
        "P00001.1",
        "-outfmt",
        "%o|%a",
    ]
    .into_iter()
    .map(str::to_string)
    .collect();
    let (rc, _out, err) = run_losat(&root.0, &db_dir, &args, &[]);
    assert_eq!(rc, 1);
    let err_str = String::from_utf8_lossy(&err);
    assert!(
        err_str.contains("past the 32 bits of a membership bitmask"),
        "{err_str}"
    );
}

#[test]
fn memb_bit_works_in_non_utf8_directory() {
    let root = TempDir::new("nonutf8");
    let bad_dir = root.0.join(std::ffi::OsStr::from_bytes(b"dir_\xff_mb"));
    copy_tree(&fixtures().join("db"), &bad_dir);

    let output = Command::new(env!("CARGO_BIN_EXE_losat"))
        .current_dir(&bad_dir)
        .env("HOME", &root.0)
        .env_remove("BLASTDB")
        .args([
            "blastdbcmd",
            "-db",
            "mb_1",
            "-dbtype",
            "prot",
            "-entry",
            "all",
            "-outfmt",
            "%o|%a|%t",
        ])
        .output()
        .expect("run losat in non-utf8 dir");
    assert_eq!(
        output.status.code(),
        Some(0),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        output.stdout,
        b"0|P00001.1|seq0_dl0 bit1\n\
          1|NP_000001.1|seq1_dl0 bit1and3\n\
          1|XP_000001.1|seq1_dl1 bit1model_twoints\n"
    );
}
